    private void jButton1ActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_jButton1ActionPerformed
        
        
        
        jLabel1.setText(jTable1.getValueAt(jTable1.getSelectedRow(), 0) + "");
        jLabel2.setText(jTable1.getValueAt(jTable1.getSelectedRow(), 1) + "");
        jLabel3.setText(jTable1.getValueAt(jTable1.getSelectedRow(), 2) + "");
        jLabel8.setText(jTable1.getValueAt(jTable1.getSelectedRow(), 3) + "");
        
        
        
    }//GEN-LAST:event_jButton1ActionPerformed

