    private void jButton2ActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_jButton2ActionPerformed
        
        jTable1.setRowHeight(Integer.parseInt(jTextField1.getText()));
        
        jTable1.getColumnModel().getColumn(0).setPreferredWidth(Integer.parseInt(jTextField2.getText()));
        jTable1.getColumnModel().getColumn(1).setPreferredWidth(Integer.parseInt(jTextField2.getText()));
        jTable1.getColumnModel().getColumn(2).setPreferredWidth(Integer.parseInt(jTextField2.getText()));
        
    }//GEN-LAST:event_jButton2ActionPerformed

